async (pid) => {
     const attempts = [
       { label: 'json.projectId', input: { json: { projectId: pid } } },
       { label: 'json string', input: { json: pid } },
       { label: 'projects/ prefix', input: { json: { projectId: 'projects/' + pid } } },
     ];
     const out = [];
     for (const a of attempts) {
       const url = '/fx/api/trpc/flow.projectInitialData?input=' + encodeURIComponent(JSON.stringify(a.input));
       const res = await fetch(url, { credentials: 'include' });
       const text = await res.text();
       let body = null;
       try { body = JSON.parse(text); } catch {}
       const result = body?.result?.data?.json?.result;
       const cfg = result?.modelConfig;
       out.push({
         label: a.label,
         httpStatus: res.status,
         innerStatus: body?.result?.data?.json?.status ?? null,
         resultKeys: result ? Object.keys(result) : null,
         hasModelConfig: Boolean(cfg),
         snippet: cfg ? null : text.slice(0, 240),
       });
       if (cfg) {
         const fam = cfg.videoModelFamilies || [];
         const first = fam[0] || {};
         const usages = Object.values(first.usages || {});
         out[out.length - 1].detail = {
           configKeys: Object.keys(cfg),
           familyCount: fam.length,
           familyKeys: Object.keys(first),
           usageCount: usages.length,
           sampleUsage: usages[0] ?? null,
         };
         break;
       }
     }
     return out;
   }
